mapper.select:
SELECT wad.id, wad.different_amount , wad.different_amount_excluding_vat , wad.serial_number adjustSerialNumber, wad.create_time, wid.id inboundDetailId, wid.basic_class, wid.material_sn, wid.classify_name, wid.specification, wid.length, wid.width, wid.thickness, wid.heat_no_and_batch_no, wid.brand, wi.serial_number serialNumber, wid.project_id, wid.heat_no_and_batch_no, wi.id inboundId, wi.inbound_way, wid.classify_id classifyId FROM wms_adjust_detail wad LEFT JOIN wms_inbound_detail wid ON wad.inbound_detail_id = wid.id LEFT JOIN wms_inbound wi ON wi.id = wid.inbound_id LEFT JOIN wms_adjust wa ON wa.id = wad.adjust_id WHERE wad.bool_delete_enum = 0
and wa.review_status = #{reviewStatus}
and wid.basic_class & #{ basicClass} > 0
and wi.purchase_sn like CONCAT('%', #{purchaseSN},'%')
and wad.create_time > #{inboundTime[0]}
and wad.create_time < #{inboundTime[1]}
and wid.project_id is null
and wid.project_id IS NOT NULL
and wid.project_id = #{projectId}
and wa.serial_number like CONCAT('%', #{adjustSerialNumber},'%')
and wi.serial_number like CONCAT('%', #{serialNumber},'%')
and wa.applicant_name like CONCAT('%', #{operatorName},'%')
and wid.workshop_id in
#{item}
and wi.inbound_way = #{inboundWay}
